<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { listProducts } from '@/api/business/product'
import { deleteAttribute, deleteAttributeValue, deleteSku, generateSkus, listAttributes, listSkus, saveAttribute, saveAttributeValue, saveSku } from '@/api/business/sku'
import FilterBar from '@/components/business/FilterBar.vue'
import SkuForm from '@/components/business/SkuForm.vue'
import StockAdjustDialog from '@/components/business/StockAdjustDialog.vue'
const products=ref([]),rows=ref([]),attributes=ref([]),total=ref(0),loading=ref(false),dialog=ref(false),saving=ref(false),attrDialog=ref(false),stockDialog=ref(null)
const query=reactive({page:1,size:10,productId:null,keyword:''})
const form=reactive({id:null,title:'',description:'',price:.01,originalPrice:null,stock:0,productId:null,skuCode:'',attributeValueIds:[]})
const selectedValues=reactive({}),generateForm=reactive({defaultPrice:.01,defaultStock:0})
const selections=computed(()=>attributes.value.map(a=>({attributeId:a.id,valueIds:selectedValues[a.id]||[]})).filter(x=>x.valueIds.length))
async function load(){loading.value=true;try{const data=await listSkus(query);rows.value=data?.records||data?.list||[];total.value=Number(data?.total||rows.value.length)}finally{loading.value=false}}
function edit(row={}){Object.assign(form,{id:null,title:'',description:'',price:.01,originalPrice:null,stock:0,productId:query.productId,skuCode:'',attributeValueIds:[],...row});dialog.value=true}
async function save(){saving.value=true;try{await saveSku(form);dialog.value=false;load()}finally{saving.value=false}}
async function remove(row){await ElMessageBox.confirm(`删除 SKU“${row.title}”？`,'危险操作',{type:'warning'});await deleteSku(row.id,row.productId);load()}
function adjustStock(row){stockDialog.value?.show(row)}
async function openAttrs(){if(!query.productId)return ElMessage.warning('请先选择商品');attributes.value=await listAttributes(query.productId);for(const a of attributes.value)selectedValues[a.id]=a.values.map(v=>v.id);attrDialog.value=true}
async function addAttr(){await saveAttribute({productId:query.productId,name:`规格 ${attributes.value.length+1}`,sort:99});attributes.value=await listAttributes(query.productId)}
async function renameAttr(a){await saveAttribute({id:a.id,productId:query.productId,name:a.name,sort:a.sort??99})}
async function addValue(a){const value=prompt(`新增“${a.name}”的规格值`);if(!value)return;await saveAttributeValue({productId:query.productId,attributeId:a.id,value,sort:99});attributes.value=await listAttributes(query.productId)}
async function removeAttr(a){await ElMessageBox.confirm(`删除规格“${a.name}”？`,'确认',{type:'warning'});await deleteAttribute(a.id);attributes.value=await listAttributes(query.productId)}
async function removeValue(v){await deleteAttributeValue(v.id);attributes.value=await listAttributes(query.productId)}
async function generate(){await generateSkus({productId:query.productId,selections:selections.value,...generateForm});attrDialog.value=false;load()}
onMounted(async()=>{const data=await listProducts({page:1,size:100});products.value=data?.records||data?.list||[];load()})
</script>
<template><div class="page"><header><small>SKU MATRIX</small><h1>SKU 与规格</h1></header><FilterBar><el-select v-model="query.productId" clearable filterable placeholder="所属商品" @change="query.page=1;load()"><el-option v-for="p in products" :key="p.id" :label="p.title" :value="p.id"/></el-select><el-input v-model="query.keyword" placeholder="SKU 关键词"/><template #actions><el-button @click="load">筛选</el-button><el-button @click="openAttrs">规格矩阵</el-button><el-button type="primary" @click="edit()">新增 SKU</el-button></template></FilterBar><section class="table-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="title" label="SKU 标题" min-width="160"/><el-table-column prop="productTitle" label="商品" min-width="160"/><el-table-column prop="skuCode" label="编码" width="140"/><el-table-column prop="price" label="现价" width="100"/><el-table-column label="原价" width="100"><template #default="{row}">{{ row.originalPrice ?? '-' }}</template></el-table-column><el-table-column prop="stock" label="库存" width="90"/><el-table-column prop="version" label="版本" width="74"/><el-table-column label="规格值" min-width="170"><template #default="{row}">{{ row.attributeValueIds?.join(' / ')||'默认规格' }}</template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link @click="adjustStock(row)">调库存</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" :page-size="query.size" :total="total" @current-change="load"/></section>
<el-dialog v-model="dialog" :title="form.id?'编辑 SKU':'新增 SKU'" width="620px"><SkuForm :form="form" :products="products"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="attrDialog" title="规格属性与笛卡尔生成" width="760px"><div class="attr-head"><p>维护规格后，勾选参与组合的值并生成 SKU。重复生成是幂等的。</p><el-button @click="addAttr">新增规格</el-button></div><section class="attrs"><article v-for="a in attributes" :key="a.id"><div class="attr-title"><el-input v-model="a.name" @change="renameAttr(a)"/><el-button link @click="addValue(a)">新增值</el-button><el-button link type="danger" @click="removeAttr(a)">删除规格</el-button></div><el-checkbox-group v-model="selectedValues[a.id]"><el-checkbox v-for="v in a.values" :key="v.id" :value="v.id"><span>{{ v.value }}</span><button class="x" @click.prevent="removeValue(v)">×</button></el-checkbox></el-checkbox-group></article></section><div class="defaults"><label>默认价格 <el-input-number v-model="generateForm.defaultPrice" :min=".01" :precision="2"/></label><label>默认库存 <el-input-number v-model="generateForm.defaultStock" :min="0"/></label></div><template #footer><el-button @click="attrDialog=false">关闭</el-button><el-button type="primary" :disabled="!selections.length" @click="generate">生成 SKU</el-button></template></el-dialog>
<StockAdjustDialog ref="stockDialog" @saved="load"/></div></template>
<style scoped>.page{display:grid;gap:18px}header small{color:var(--c-moss-dark)}h1{font-family:var(--font-pixel);color:var(--c-wood-dark)}.table-card{padding:14px;border:3px solid var(--c-wood-dark);background:var(--c-surface);box-shadow:var(--shadow-pixel);overflow:auto}.attr-head,.attr-title,.defaults{display:flex;align-items:center;gap:12px}.attr-head{justify-content:space-between}.attrs{display:grid;gap:12px;margin:14px 0}.attrs article{padding:12px;border:2px solid var(--c-wood);background:var(--c-surface-2)}.attr-title .el-input{max-width:240px}.x{margin-left:4px;border:0;background:transparent;color:var(--c-brick);cursor:pointer}.defaults{justify-content:flex-end}</style>
